from pathlib import Path
import json,datetime,hashlib
out=Path('/private/tmp/frontier-plan-completion/council-delivery')
ledger=json.loads((out/'results.json').read_text())
observations=ledger.setdefault('native_phases',[])
known={(r['agent_id'],r['phase_number']) for r in observations}
for path in Path('/Users/medhat.galal/.codex/sessions/2026/09/08').glob('*.jsonl'):
    with path.open() as f:
        try: first=json.loads(f.readline())
        except ValueError: continue
        meta=first.get('payload',{})
        name=meta.get('agent_path','')
        if not name.startswith('/root/verify_council_and_delivery/'): continue
        ctx={};trace=[];phase=0;start=meta.get('timestamp')
        for line in f:
            try: d=json.loads(line)
            except ValueError: continue
            p=d.get('payload',{})
            if d.get('type')=='turn_context':
                ctx={k:p.get(k) for k in ('model','effort','reasoning_effort','cwd')}
            elif d.get('type')=='response_item' and p.get('type') in ('function_call','custom_tool_call','function_call_output','custom_tool_call_output'):
                trace.append({'timestamp':d.get('timestamp'),'type':p.get('type'),'name':p.get('name'),'call_id':p.get('call_id'),'arguments':p.get('arguments'),'input':p.get('input'),'output':p.get('output')})
            elif d.get('type')=='event_msg' and p.get('type')=='task_complete':
                phase+=1
                end=p.get('completed_at') or d.get('timestamp')
                if (meta.get('id'),phase) not in known:
                    output=p.get('last_agent_message','')
                    observations.append({'agent_path':name,'agent_id':meta.get('id'),'phase_number':phase,'session_path':str(path),'session_cli_version':meta.get('cli_version'),'host_turn_context':ctx.copy(),'phase_started_at':p.get('started_at') or start,'completed_at':end,'captured_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'output':output,'output_sha256':hashlib.sha256(output.encode()).hexdigest(),'outward_tool_trace':trace.copy(),'trace_scope':'Selected host metadata, outward tool calls/results and task-complete final only; no private reasoning. Persisted inbound prompts may be opaque; dispatched prompt text recorded by controller, not independently decrypted.'})
                start=end;trace=[]
(out/'results.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
